import type { ChipBarProps } from "./chip-bar.types";
import type { ChipProps } from "../chip/chip.types";

import React, { forwardRef, Children, cloneElement, isValidElement, useRef, useMemo } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Check as CheckIcon } from "@exp-textura/icons";
import { useMergeRefs } from "@system";
import { Popover } from "@components/popover";
import { Chip } from "@components/chip";

import { ChipBarClasses, StyledChipBar } from "./chip-bar.styles";
import { useChipBar } from "./hooks/use-chip-bar";
import { useVisibleChipBar } from "./hooks/use-visible-chip-bar";

const ChipBarOverflow: React.FC<{
  overflowChips: React.ReactElement[];
  moreButtonRef: React.RefObject<HTMLSpanElement>;
  size?: "default" | "sm";
}> = ({ overflowChips, moreButtonRef, size }) => {
  const count = overflowChips.length;

  return (
    <Popover dismissable>
      <Popover.Trigger>
        <Chip ref={moreButtonRef} isOverflow size={size}>
          +{count}
        </Chip>
      </Popover.Trigger>
      <Popover.Content>
        <div className={ChipBarClasses.overflowContent}>{overflowChips}</div>
      </Popover.Content>
    </Popover>
  );
};

const ChipBar = forwardRef<HTMLDivElement, ChipBarProps>(
  (
    {
      className,
      variant = "default",
      selectionMode = "none",
      value: valueProp,
      defaultValue,
      onChange,
      selectedIcon = <CheckIcon />,
      enableOverflow = true,
      size,
      children,
      ...props
    }: ChipBarProps,
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(ChipBarClasses.root, className);
    const containerRef = useRef<HTMLDivElement>(null);
    const moreButtonRef = useRef<HTMLSpanElement>(null);
    const mergedRef = useMergeRefs(ref, containerRef);
    const [closedValues, setClosedValues] = React.useState<string[]>([]);

    const { selectedValue, handleChipClick, chipBarRole, chipWrapperRole } = useChipBar({
      value: valueProp,
      defaultValue,
      onChange,
      selectionMode,
    });

    const childrenWithIds = useMemo(() => {
      return Children.toArray(children).map((child, index) => ({
        child: child as React.ReactElement,
        id:
          (isValidElement(child) ? (child.props as ChipProps).value : undefined) ||
          `generated-chip-${index}`,
      }));
    }, [children]);

    const validChildrenItems = useMemo(() => {
      return childrenWithIds.filter(
        (item) =>
          isValidElement(item.child) &&
          (item.child.props as ChipProps).show !== false &&
          !closedValues.includes(item.id),
      );
    }, [childrenWithIds, closedValues]);

    const allValues = useMemo(
      () => validChildrenItems.map((item) => item.id),
      [validChildrenItems],
    );

    const { visibleValues: hookVisibleValues, overflowValues: hookOverflowValues } =
      useVisibleChipBar(containerRef, enableOverflow ? allValues : [], moreButtonRef);

    const visibleValues = enableOverflow ? hookVisibleValues : allValues;
    const overflowValues = enableOverflow ? hookOverflowValues : [];

    const renderChip = (item: { child: React.ReactElement; id: string }, isOverflow = false) => {
      const { child, id: chipValue } = item;

      const isSelected =
        selectionMode === "multiple"
          ? ((selectedValue as string[]) || []).includes(chipValue)
          : selectedValue === chipValue;

      const wrapperClasses = clsx(ChipBarClasses.chipWrapper, {
        [ChipBarClasses.chipWrapperSelected]: isSelected,
        [ChipBarClasses.chipWrapperSelectable]: selectionMode !== "none",
      });

      return cloneElement(
        child,
        {
          ...child.props,
          className: clsx(child.props.className, wrapperClasses),
          variant: child.props.variant || "neutral",
          type: child.props.type || "outline",
          size: child.props.size || size, // Cascade size if not overridden
          role: chipWrapperRole,
          "aria-checked": selectionMode !== "none" ? isSelected : undefined,
          "data-value": !isOverflow ? chipValue : undefined,
          style: {
            ...child.props.style,
            ...(!isOverflow && enableOverflow && !visibleValues.includes(chipValue)
              ? { visibility: "hidden", position: "absolute", zIndex: -1 }
              : undefined),
          },
          tabIndex: selectionMode !== "none" ? 0 : undefined,
          onClick: (e: React.MouseEvent) => {
            child.props.onClick?.(e);
            handleChipClick(child.props.value || chipValue);
          },
          onClose: () => {
            child.props.onClose?.();
            setClosedValues((prev) => [...prev, chipValue]);
          },
          onKeyDown: (e: React.KeyboardEvent) => {
            child.props.onKeyDown?.(e);
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              handleChipClick(child.props.value || chipValue);
            }
          },
        },
        isSelected ? selectedIcon : null,
        child.props.children,
      ) as React.ReactElement<ChipProps>;
    };

    const overflowChips = validChildrenItems
      .filter((item) => overflowValues.includes(item.id))
      .map((item) => renderChip(item, true));

    return (
      <StyledChipBar
        ref={mergedRef}
        className={rootClasses}
        currentTheme={theme}
        role={chipBarRole}
        variant={variant}
        {...props}
      >
        {validChildrenItems.map((item) => renderChip(item))}
        {overflowValues.length > 0 && (
          <ChipBarOverflow
            moreButtonRef={moreButtonRef}
            overflowChips={overflowChips}
            size={size}
          />
        )}
      </StyledChipBar>
    );
  },
);
ChipBar.displayName = "ChipBar";

export default ChipBar;
